using Printf

#bts = Any[]
badtensors = nothing
for i in 1:20
    println()
    global badtensors
    dat = read(`java -jar /tmp/gamut -random_params -players 6 -actions 5 -normalize -min_payoff -1 -max_payoff 1 -output GambitOutput -f /dev/stdout -g UniformLEG-RG`);
    tensors = parse_nfg(dat);
#tensors,acts = eliminate_dominated_strategies(_tensors)
#@show acts
    ne, st = solve(tensors; stop_lambda=1e6, stop_eps=NaN, stop_iters=5000);
    if st.lambda <= 500000 && st.regret > 0.0
        @warn st
    else

        @info "$(round(min(st.lambda,1000000.0);digits=6)),$(join(round.(vcat(ne...);digits=3),","))"

    end

    gamb = `gambit-logit -qe -d3 -l1000000 -m0.0`
    bytes2 = read(pipeline(gamb, stdin=IOBuffer(dat)))
    final_result = String(bytes2)
    flts = parse.(Float64, split(final_result, ","))
    println("gambit: ",(join(round.(flts;digits=3),",")))

    if norm(vcat(ne...) - flts[2:end]) >= 1e-3 || st.lambda <= 500000 && st.regret > 0.0
        @warn "pushing"
        push!(bts, tensors);
    end
end


#=
for (i,game) in enumerate(bts)
           letter = ('a':'z')[i]
           open(io -> write(io, export_gambit_format_buf(game)), "/tmp/leg.$letter.nfg", "w")
       end


